parameters.jsCode:
const draft = $input.first().json;
const webhookRaw = $('1. Human Action Webhook Trigger').first().json;
const webhookBody = webhookRaw.body || webhookRaw;

const recipientEmail = String(draft.recipient_email || 'client@enterprise.com').trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const isValidEmail = emailRegex.test(recipientEmail);

if (!isValidEmail) {
  throw new Error(`Địa chỉ email người nhận không hợp lệ cú pháp: ${recipientEmail}`);
}

// Ưu tiên nội dung đã qua chỉnh sửa từ Human Reviewer
const reviewerEmail = String(webhookBody.reviewer_email || 'reviewer@company.com').trim();
const finalSubject = String(webhookBody.modified_subject || draft.subject || draft.proposed_subject || 'Phản hồi hỗ trợ').trim();
const finalBody = String(webhookBody.modified_body || draft.html_content || draft.proposed_body || 'Nội dung phản hồi').trim();

const ticketCode = draft.ticket_code || draft.t_code || 'TK-UNKNOWN';
const ticketId = draft.ticket_id || draft.t_id || null;
const ticketCreatedAt = draft.ticket_created_at || draft.created_at || new Date().toISOString();
const slaDueAt = draft.sla_due_at || draft.first_response_sla || new Date(Date.now() + 24 * 3600 * 1000).toISOString();

return [{
  json: {
    ...draft,
    draft_id: draft.id,
    recipient_email: recipientEmail,
    reviewer_email: reviewerEmail,
    final_subject: finalSubject,
    final_html: finalBody,
    ticket_code: ticketCode,
    ticket_id: ticketId,
    ticket_created_at: ticketCreatedAt,
    sla_due_at: slaDueAt,
    is_valid_email: true
  }
}];

