parameters.jsCode:
const draft = $('4. Email Address Validation Code').first().json;

const sentAt = new Date();
const createdAt = new Date(draft.ticket_created_at || Date.now());
const resolutionTimeMs = Math.max(0, sentAt.getTime() - createdAt.getTime());
const resolutionTimeMinutes = Math.round(resolutionTimeMs / 60000);

const slaDueAt = new Date(draft.sla_due_at || (createdAt.getTime() + 24 * 3600 * 1000));
const isMetSla = sentAt.getTime() <= slaDueAt.getTime();
const slaStatus = isMetSla ? 'MET_SLA' : 'BREACHED_SLA';

return [{
  json: {
    ...draft,
    sent_at: sentAt.toISOString(),
    resolution_time_ms: resolutionTimeMs,
    resolution_time_minutes: resolutionTimeMinutes,
    is_met_sla: isMetSla,
    sla_status: slaStatus
  }
}];

